import{_ as a,c as t,aU as s,a as r}from"./chunks/framework.DIXiA2XH.js";const e="/assets/26.D2v8yWLB.png",o="/assets/1.NkAlL5sD.png",i="/assets/2.IFdTARbx.png",n="/assets/3.CKEU6eYm.png",l="/assets/4.UcLVvmoY.png",h="/assets/5.DXiO5b15.png",c="/assets/6.CEwH_qLG.png",d="/assets/7.CaAEpvOn.png",g="/assets/8.C_6Ol6e3.png",m="/assets/9.D9aNBqI-.png",_="/assets/10.B_DFnMsc.png",u="/assets/11.DVEtk2KS.png",b="/assets/12.CZXCK5Mt.png",q="/assets/13.CUtUqAXI.png",x="/assets/14.Kbonw-I2.png",f="/assets/15.QLY6kFl0.png",P="/assets/16.DRxRpg9W.png",k="/assets/17.Dpy-1hvB.png",C="/assets/18.Dsu9H0c6.png",B="/assets/19.DZ_iPSzl.png",D="/assets/20.CSw5MRo1.png",N="/assets/21.03U0MTNj.png",A="/assets/22.CzGJh915.png",S="/assets/23.tF_HJ2G2.png",U="/assets/24.ZiiQRO8L.png",v="/assets/25.DiW7d6Qr.png",I=JSON.parse('{"title":"几何王国","description":"","frontmatter":{},"headers":[],"relativePath":"note/game/jihewangguo/index.md","filePath":"note/game/jihewangguo/index.md","lastUpdated":1767453469000}'),w={name:"note/game/jihewangguo/index.md"};function E(L,p,T,O,R,j){return r(),t("div",null,[...p[0]||(p[0]=[s('<h1 id="几何王国" tabindex="-1">几何王国 <a class="header-anchor" href="#几何王国" aria-label="Permalink to &quot;几何王国&quot;">​</a></h1><h2 id="钓鱼" tabindex="-1">钓鱼 <a class="header-anchor" href="#钓鱼" aria-label="Permalink to &quot;钓鱼&quot;">​</a></h2><p><img src="'+e+'" alt=""></p><h2 id="几何王国游戏攻略-钓鱼-鱼缸搭配-英雄推荐" tabindex="-1">几何王国游戏攻略/钓鱼/鱼缸搭配/英雄推荐 <a class="header-anchor" href="#几何王国游戏攻略-钓鱼-鱼缸搭配-英雄推荐" aria-label="Permalink to &quot;几何王国游戏攻略/钓鱼/鱼缸搭配/英雄推荐&quot;">​</a></h2><p>在术士、爷爷、船长、骨弓等一众强势新英雄得到合理开发以及精灵系统出现前，大家基本上是按照传统阵容（见图1）来进行英雄搭配，传统阵容在于每个英雄技能相对均衡，伤害、控制、增益、减益均有，不存在明显短板。所以在雕文、觉醒技能、神器培养差不多的情况下，传统阵容优势较大。</p><p><img src="'+o+'" alt=""> 随着精灵系统的加入，弥补了部分英雄的技能短板，再加上新英雄的成型，涌现出了更多元的阵容搭配，以往的万精油阵容也渐渐消失。笔者结合各英雄的技能特征，试验出暴力推进队、前排杀手队、后排杀手队、控制折磨队4类特色阵容（见图2），接下来将从阵容解读，鱼选择、精灵选择三方面为大家提供详细的搭配攻略 <img src="'+i+'" alt=""></p><p><strong>No.1暴力推进队</strong></p><p>（1）阵容解读：该阵容源于船长和术士的加入，以往推进主要靠酒仙和铁扇公主，酒仙的弱点在于推进效果突出，但缺少伤害，铁扇公主的弱点在于推进主要为被动抵抗而非主动推进 而船长的幽灵船和舰船突袭既有高额伤害有带大幅击退，术士的地狱火有强大的推进能力并且还能作为前排分摊伤害，船长+术士在推进及伤害综合表现上都优于酒仙+铁扇公主 推荐阵容为：黑暗骑士+船长+术士+铁扇公主+巫妖王，船长可替换为剑圣（剑圣的剑刃风暴也有很强的击退能力），铁扇公主可替换为沉默（如果不用铁扇公主队伍已经有很强的推进能力就可以换成沉默增加额外控制效果）</p><p>（2）鱼选择：该队伍没有射手，可不考虑带暴击、爆伤的鱼。小型鱼建议熊猫鱼（回命）、桃花鱼（伤减），中型鱼建议多鳍鱼（击退抗性）、黑鮟鱇（移速），大型鱼建议皇带鱼（击退效果），水中生物建议大王具足虫（击退效果）、拟鳄龟（击退效果）</p><p>（3）精灵选择：黑暗骑士：秘法女巫/岩岩龟；船长/剑圣：翡翠之主/大地暴君；术士：魔能女士；铁扇公主：火烈猴/沉默：扎达姆；巫妖王：赤色彗星</p><p><strong>No.2前排杀手队</strong></p><p>（1）阵容解读：该阵容源于带真伤的神罗战士、李白、玉面狐妖，无视防御再加上爷爷的攻击与回能增益效果，可实现快速消灭对方前排 推荐阵容为：黑暗骑士+神罗战士+李白+爷爷+玉面狐妖，李白可替换为骨弓（骨弓的生存能力强于李白，如果玉面狐妖已经伤害很高可将李白替换为骨弓，增加伤害续航能力）</p><p>（2）鱼选择：该队伍对暴击爆伤需求较大，击退效果需求不大。小型鱼建议熊猫鱼（回命）、桃花鱼（伤减），中型鱼建议多鳍鱼（击退抗性）、黑鮟鱇（移速），大型鱼建议白海豚（暴击）、远东哲鱼（暴击）、尖刺比目鱼（爆伤）、黄金河虎（爆伤）（如果精灵有毁灭之牙，建议选后两条），水中生物建议彩虹螺（爆伤）、海星（攻速）</p><p>（3）精灵选择：黑暗骑士：秘法女巫/岩岩龟；神罗战士：大地暴君；李白：大地暴君/骨弓：火烈猴；爷爷：魔能女士；玉面狐妖：毁灭之牙。</p><p><strong>No.3后排杀手队</strong></p><p>（1）阵容解读：该阵容是原火枪队的加强版，随着精灵系统的出现，扎达姆、战甲虫、魔能女士等后排法系精灵提供了高额防御、爆伤抗性、伤害减免等属性有效限制了火枪的秒后排能力，将原沉默换成爷爷或复仇者，能增强队伍对敌方后排的伤害 如果火枪雕文很强，建议搭配爷爷为其回能和加攻击，进一步强化火枪狙击伤害，如果火枪雕文还欠缺，可将爷爷换成复仇者，利用复仇者斩击技能加上火枪狙击双重伤害对后排进行秒杀。推荐阵容为：黑暗骑士+光明骑士+火枪+爷爷+巫妖王，爷爷可替换为复仇者</p><p>（2）鱼选择：该队伍对暴击爆伤需求较大，击退效果需求不大。小型鱼建议熊猫鱼（回命）、桃花鱼（伤减），中型鱼建议多鳍鱼（击退抗性）、黑鮟鱇（移速），大型鱼建议白海豚（暴击）、远东哲鱼（暴击）、尖刺比目鱼（爆伤）、黄金河虎（爆伤）（如果精灵有毁灭之牙，建议选后两条），水中生物建议彩虹螺（爆伤）、海星（攻速）</p><p>（3）精灵选择：黑暗骑士：秘法女巫/岩岩龟；光明骑士：翡翠之主；爷爷：魔能女士/复仇者：大地暴君；巫妖王：赤色彗星；火枪：毁灭之牙</p><p><strong>No.4 控制折磨队</strong></p><p>（1）阵容解读：该阵容的原理在于通过长时间的沉默、减能技能让敌方无法释放技能，并搭配控制技能让敌方苦不堪言 推荐阵容为：疾风忍者+光明骑士+术士+沉默+海拉。疾风忍者技能带减能、沉默效果，光明骑士抗伤害提供队伍续航能力，术士技能带减能、减疗、减速效果，沉默技能带减能、沉默效果，海拉技能带减能、减疗、沉默效果，真正让敌方有一大半的时间无法释放技能，虽然单个英雄伤害不高，但其强大的控制能力能慢慢耗死对方，只是增加了作战时长</p><p>（2）鱼选择：该队伍对魔法伤害、击退需求较大。小型鱼建议熊猫鱼（回命）、桃花鱼（伤减），中型鱼建议多鳍鱼（击退抗性）、黑鮟鱇（移速），大型鱼建议皇带鱼（击退效果）、白斑狗鱼（魔伤），水中生物建议大王具足虫（击退效果）、拟鳄龟（击退效果）、大鳍鱿鱼（魔伤）</p><p>（3）精灵选择：疾风：翡翠之主；白骑：秘法女巫/岩岩龟；术士：魔能女士；沉默：扎达姆；海拉：赤色彗星 未来随着新英雄和新玩法的加入，会产生更多元化的阵容，这需要大家共同的试验与开发，希望通过笔者对当前版本的理解和英雄特征分析，能为大家在新环境下的阵容搭配提供一定帮助，有问题之处敬请指出！</p><h2 id="新手前期英雄推荐-因为在前期资源非常少的情况下-需要优先上阵星高的英雄-前期有几个比较好用的英雄可以暂时过度" tabindex="-1">新手前期英雄推荐，因为在前期资源非常少的情况下，需要优先上阵星高的英雄，前期有几个比较好用的英雄可以暂时过度 <a class="header-anchor" href="#新手前期英雄推荐-因为在前期资源非常少的情况下-需要优先上阵星高的英雄-前期有几个比较好用的英雄可以暂时过度" aria-label="Permalink to &quot;新手前期英雄推荐，因为在前期资源非常少的情况下，需要优先上阵星高的英雄，前期有几个比较好用的英雄可以暂时过度&quot;">​</a></h2><p>复仇者：获取成本较低，攻击敌人可附加流血效果。</p><p>齐天大圣：技能与普攻皆能对敌人造成高额暴击伤害，后期伤害出色。</p><p><strong>T1：</strong></p><p>骷髅王：通用性强，大招可对全体敌人施加诅咒与暴击伤害。</p><p>月之女：爆发能力极强，能在短时间内击败敌人。</p><p><strong>T2：</strong></p><p>潮壮壮：技能控制效果显著，命中敌人可致沉默，攻防兼备，泛用性良好。</p><p><strong>最强阵容推荐</strong></p><p>阵容一： 齐天大圣 + 月之女 + 牛魔 + 骷髅王 + 人鱼公主</p><p>优点： 获取与培养成本低，适合新手。骷髅王爆发强，人鱼公主可控制敌人并提升队伍输出。</p><p>阵容二： 复仇者 + 火枪 + 齐天大圣 + 潮壮壮 + 莫莫</p><p>优点： 火枪与齐天大圣输出高，队伍输出上限高。潮壮壮控制，莫莫为队友减防，生存能力较强。</p><p>后期主c推荐值得培养的英雄</p><p>战士：船长 黑暗骑士 复仇者 剑圣 神罗战士 白牛</p><p>辅助：冰女 小鹿 光明骑士 琴音仙女 术士 月光使者 沉默</p><p>射手：火枪 影魔 骷髅射手 暗器大师</p><p>法师：巫妖王 玉面狐妖 海拉 铁扇公主 深渊女王</p><h2 id="雕文攻略" tabindex="-1">雕文攻略 <a class="header-anchor" href="#雕文攻略" aria-label="Permalink to &quot;雕文攻略&quot;">​</a></h2><p><strong>1.雕文种类</strong></p><p>首先雕文分为攻击雕文，生存雕文，能量雕文，效果雕文。其中战力提升最高的就是攻击雕文与生存雕文!能量与效果雕文，战力提升很少!</p><p><strong>2.不同职业配置</strong></p><p>战士:1个攻击雕文+1个能量雕文+1个效果雕文+3个生存雕文</p><p>辅助:1个攻击雕文+2个能量雕文+2个效果雕文+1个生存雕文</p><p>射手: 3个攻击雕文+1个能量雕文+1个效果雕文+1个生存雕文</p><p>法师:2个攻击雕文+2个能量雕文+1个效果雕文+1个生存雕文</p><p><img src="'+n+'" alt=""><img src="'+l+'" alt=""><img src="'+h+'" alt=""></p><p>3.雕文品质</p><p>有普通，稀有，传说，神话，永恒，品质越高属性条越多，最高有5条属性加成!而神话合成永恒雕文需要使用强效合成剂，这个东西只有活动的时候会有或者一次性充值星砖5000起步才能获得! <img src="'+c+'" alt=""></p><p>4.雕文洗练</p><p>合成永恒雕文后才可以使用洗练石(获得方式:试炼之地里的神秘森林+每日精选商店+抵御恶魔活动+大型活动)!</p><p>雕文洗练没有技巧，全靠运气!理论上可以洗练成5S同一属性，但实际上非常困难!所以建议见好就收，般3条S以上有用的属性就可以停止洗练了!或者分数超过7500后即可!</p><p>5.雕文属性</p><p><strong>攻击雕文</strong></p><p>破甲:降低目标防御</p><p>吸血:普通攻击造成伤害时转化为生命</p><p>击退效果:增加普攻或技能所造成的击退距离</p><p>重伤效果:降低目标受到治疗的效果</p><p>攻击:增加基础攻击</p><p>暴击:造成暴击伤害的几率</p><p>暴伤:暴击时造成的伤害</p><p>伤害增加:增加所造成的伤害</p><p>物理增伤:增加造成的物理伤害</p><p>魔法增伤:增加造成的魔法伤害</p><p>排序选择:爆伤，暴击，攻击，破甲，击退效果，其中攻击属性战力提升最明显！ <img src="'+d+'" alt=""></p><p><strong>生存雕文</strong></p><p>格挡:增加格挡几率</p><p>生命:增加基础生命</p><p>防御:增加基础防御</p><p>免暴率:降低被暴击几率</p><p>物理抗性:降低物理伤害</p><p>魔法抗性:降低魔法伤害</p><p>伤害减免:降低最终的伤害结果</p><p>近战减伤:降低近战攻击带来的伤害</p><p>远程减伤:降低远程攻击带来的伤害</p><p>暴伤抗性:降低受到暴击所造成的伤害</p><p>排序选择:爆伤减免，免爆率，生命，防御，伤害减免，远程减伤。其中生命战力其实最大，其次是防御!</p><p><strong>能量雕文</strong></p><p>攻击回能:普通攻击增加能量</p><p>攻击减能普通攻击减少目标能量</p><p>受击回能:每次受到普通攻击增加能量</p><p>能量回复:增加每秒能量回复</p><p>能量增加:增加英雄初始能量</p><p>能量结余:英雄释放大招后剩余能量</p><p>战败回能:场上每名英雄被击败时获得能量</p><p>自爆减能:被击败后减少击杀者能量</p><p>前排英雄:优先受击回能，能量结余，能量回复，自爆减能后排英雄:优先攻击回能，攻击减能，能量增加，能量回复，战败回能</p><p><strong>效果雕文</strong></p><p>免控率:降低被控制的几率</p><p>闪避:增加闪避几率</p><p>反伤:将受到的伤害反馈给攻击者</p><p>治疗:增加治疗量</p><p>受愈:增加受到治疗的效果</p><p>生命回复:增加每秒最大生命回复效果</p><p>攻击速度:增加每次普通攻击的速度</p><p>击退抗性:降低被击退的距离</p><p>减速抗性:降低受到减速效果的英雄</p><p>控制抗性:降低被控制的时间</p><p>移动速度:增加移动速度</p><p>前排英雄:优先生命回复，击退抗性，移动速度，控制抗性，减速抗性辅助英雄:优先治疗，生命回复，控制抗性后排输出英雄:优先攻击速度，生命回复，控制抗性</p><h2 id="神格攻略" tabindex="-1">神格攻略 <a class="header-anchor" href="#神格攻略" aria-label="Permalink to &quot;神格攻略&quot;">​</a></h2><p>神格包含三种颜色和三级属性，三种颜色为蓝、黄、红，三级属性为单体属性(初级生命、初级攻击等)、各职业属性(战士生命、法师攻击等)、全体属性(全体生命、全体攻击等)。要清楚全体属性和各职业属性的神格是全员均享的，所以除三支上阵英雄外的英雄一定是加全体属性，其次加各职业属性。而单体属性神格般数值比较高，适合上阵英雄升级。另外，升级神格每级增加属性不变，但每级花费灵石会更多，所以一定要平均升级，不要只对一个英雄的神格升级，这样带来的属性收益会更大。以下三张图是笔者根据各职业对属性需求的优先级，针对蓝、黄、红三类神格，整理的上阵英雄和非上阵英雄升级神格的先后顺序，大家对照图升级各职业神格即可。</p><p><img src="'+g+'" alt=""><img src="'+m+'" alt=""><img src="'+_+'" alt=""></p><p>PS:1、蓝、黄神图标下方为每级属性增加数值;2、红色神格基本均为全体属性，所以不用分职业升级。我们长期致力于提供更实用的通用攻略，并持续更新有关数据算计和各种活动玩法攻略，希望帮助热爱几何王国的玩家，祝大家游戏愉快</p><h2 id="远古遗迹攻略大全" tabindex="-1">远古遗迹攻略大全 <a class="header-anchor" href="#远古遗迹攻略大全" aria-label="Permalink to &quot;远古遗迹攻略大全&quot;">​</a></h2><p>玩法规则:</p><p>1.只能对当前搜寻到的遗迹进行探索，每天首次搜寻免费，免费次数每日05:00重置</p><p>2.遗迹地图共3层，不同的遗迹有不同的探索奖励</p><p>3.在遗迹地图中，点击相邻地块即可探索此地块，每次探索都要消耗1点体力，体力每30分钟恢复1点</p><p>4.地块下方隐藏着各种奖励，也隐藏着怪物和各类特殊事件</p><p>5.点击奖励即可完成奖励拾取</p><p>6.怪物会封锁周围的地块，只有击败怪物才可以探索怪物周围的地块，每次与怪物战斗都需要消耗2点体力(不论胜败)</p><p>7.无法前往路障所在的地块，无法探索只和路障相邻的地块</p><p>8.如果拾取到闪电术，可以用其消灭遗迹中的怪物;如果拾取到火球术，可以用其清除遗迹中的路障</p><p>9.当次探索中拾取到的闪电术和火球术不会保留到下一次探索，但每次探索开始时会自动获得一张闪电术和张火球术</p><p>10.某些地块下方隐藏着任务NPC，9完成任务即可从NPC处获得丰厚的奖励11.在遗迹的最后一层有终极宝箱，领取终极宝箱后，您可以选择继续探索该遗迹，也可以随时终止本次探索并带走全部已获得的奖励</p><p>遗迹列表:</p><p>1.日前总共有11个遗迹，每天免费刷新搜寻的遗迹大概率会是第一个小型遗迹，可通过花费50砖石再次进行搜寻，直到搜到你想要遗迹(大型遗迹任务资源奖励多，但是刷新成本偏高，谨慎选择)。每个遗迹主要对应的图画箱不一样，可根据自己想要的英雄皮肤，去选择遗迹。</p><p><img src="'+u+'" alt=""><img src="'+b+'" alt=""></p><p>2.其中上古遗迹是需要集齐50个地图碎片才可以进入。终极宝箱以及遗迹任务奖励丰厚!只是秘境传送门(通常出现在第二层)有两种奖励，一种是全宝箱拾起!另外一种就是用砖石购买资源!虽然贩卖的数量比一般地图多，所以砖石价格也贵了一些! <img src="'+q+'" alt=""></p><p>探索攻略:</p><p>1.进入探索，建议先直奔最终的宝箱，拿了之后，再去寻找其他的奖励!建议每天至少把传送门和遗迹任务都找到再结束，这里面的奖励也很不错。</p><p>2.遗迹任务也叫做特殊事件(NPC通常出现在第三层)，遇到铁扇任务:她会让你去打怪(会提示在第几层才能找到怪物)，这个任务需要注意下是否已经打过了，因为打完需要回去点铁扇，才能领奖励!不会自己弹出来避免浪费体力。</p><p>3.遇到火女会让你去找帽子(会提示在第几层才能找到帽子)。</p><p>4.遇到哥布林商人，买东西75折，建议都拿下。</p><p>5.有时运气好会刷到双遗迹任务，其中一个NPC通常在第一层才能找到!</p><p>6.途中遇到怪物或者树桩，先绕路走，不要急着打，看后面能不能找到闪电卡和火球卡</p><p>7.权益卡性价比还可以，每个月60块，可以多很多体力和遗迹而</p><p><img src="'+x+'" alt=""></p><p>遗迹商店</p><p>遗迹商店推荐买图画箱和神话灵石!不建议买神庙地图碎片!</p><h2 id="秘境攻略" tabindex="-1">秘境攻略 <a class="header-anchor" href="#秘境攻略" aria-label="Permalink to &quot;秘境攻略&quot;">​</a></h2><p>幻兽秘境《巨龙+肉山大魔王》</p><h3 id="巨龙守卫" tabindex="-1">巨龙守卫 <a class="header-anchor" href="#巨龙守卫" aria-label="Permalink to &quot;巨龙守卫&quot;">​</a></h3><p>技能一「巨龙火焰」</p><p>向前方持续喷射火焰，对所有敌人造成3段150%的魔法伤害，被火焰击中的敌人在5秒内每秒流失2%最大生 命值与80点能量。</p><p>总结:每秒损失2%生命和80点能量非常牛。所以打巨龙带爷爷的快速回能作用非常明显!而且还附带回血!</p><p>技能二「火焰流星」 召唤5颗灼热的熔岩随机砸向敌人，每颗熔岩会对敌人造成150%魔法伤害并附带短暂的眩晕效果。</p><p>总结:这个技能伤害一般，眩晕短暂。</p><p>技能三「龙鳞铠甲」</p><p>受到攻击时，降低攻击者15%攻击力，效果持续5秒(不可叠加)。被动:受到物理攻击时，有60%概率降低75%伤害。</p><p>总结:这个技能决定了只能用法师才能打出伤害。</p><p>技能四「狂暴」每损失一定血量，叠加一层能力。总结:我方打出伤害越高，boss打我们的伤害就越高</p><p>英雄推荐:</p><p>奶妈:爷爷</p><p>法师:狐狸，海拉</p><p>辅助:月光使者，沉默</p><p>前排:路西法(放大对boss有效)，黑骑</p><h3 id="肉山大魔王" tabindex="-1">肉山大魔王 <a class="header-anchor" href="#肉山大魔王" aria-label="Permalink to &quot;肉山大魔王&quot;">​</a></h3><p>技能- 「愤怒咆哮」</p><p>发出怒吼对路径上的所有敌人造成200%物理伤害与20%已经损失生命值的伤害总结:我方血量越少，它对我方的伤害就越高，而且基本都是在二技能后面释放，所以需要尽量持续保持血量充足的状态!</p><p>技能二 「大地锤击」</p><p>战场上存在2名以上敌人时，连续锤击地面3次，锤击时自身处于霸体状态无法被控制。第一次:对前方200码的敌人造成120%物理伤害，并附带35%减速;第一次:对前方300码的敌人造成180%物理伤害并附带60%减速第三次:对前方所有敌人造成250%物理伤害并附带1.5秒眩量。</p><p>总结:三连击对前方300码内的敌人伤害非常高，很强势的一个技能，击退效果很强，释放后会马上释放一技能收割，伤害很高!</p><p>技能三 「法术抵抗」</p><p>自身免疫所有减益效果，并且战斗开始后每秒增加自身2%魔法抗性(最多叠加至80%)。</p><p>总结:所以控制类法师与辅助基本没多大的作用!只能用物理英雄!</p><p>技能四「狂暴」每损失一定血量，看加一层能力。总结:我方输出越高，boss对我方的伤害就越高:</p><p>英雄推荐:</p><p>奶妈:爷爷，白骑</p><p>射手:骨弓，隐踪，李白，火枪，月之女前排:复仇，神罗，船长，剑圣，路西法</p><h2 id="黑暗之门攻略大全" tabindex="-1">黑暗之门攻略大全 <a class="header-anchor" href="#黑暗之门攻略大全" aria-label="Permalink to &quot;黑暗之门攻略大全&quot;">​</a></h2><p>A:军需官</p><p>每次挑战后可以获得恶魔硬币，恶魔硬而可以在军需官这里使用升级技能，技能升级后随时可以撤销加点</p><p>加点顺序建议:</p><ol><li>上阵英雄点满需要1440币</li><li>装备栏点满霅要900币。</li><li>空投补给点满需要1080币.</li><li>技能强化点满需要13240币。</li><li>最终伤害是个无底洞，最后全部点这个。</li></ol><p>B:出战技能，技能升满级效果如下:</p><ol><li>神域圣光，耗费:120点充能 满级效果:清除所有友军的负面效果且立即回复65%最大生命，并且所有友军会在5秒内每秒回复20%的能罩。</li><li>雷霆一击，耗费:100点充能满级效果:在20秒内每秒召唤一次闪电攻击战场内的所有敌人，闪电每次会对敌人造成120000+20%最大生命的伤害并附带打断效果。</li><li>庇护之盾，耗费:70点充能满级效果:为最虚弱的一名友军增加一个持续10秒的护盾，护盾会增加友军30%伤害减免并且每秒为友军口复12%最大生命值。</li><li>嗜血，耗费:120点充能 满级效果:增加己方所有英雄48%吸血和58%攻击，效果持续30秒。</li><li>缓慢愈合，耗费:140点充能 满级效果:每秒为全体友军回复12%最大生命值，效果持续30秒。</li><li>无畏耗费:140点充能满级效果:立即增加全体友军38%击退抗性与48%伤害减免，效果随着时间逐渐衰减。</li></ol><p>总结:出战技能推荐使用缓慢愈合，回复量超多，30秒内可以保证全体都满血，起死回生的神技!其他技能保命效果差，一旦受到重创，很容易就暴毙了!</p><p>C:阵容推荐:</p><p>前5个位置:两个辅助位，1个输出位，2个前排位。</p><ol><li>辅助位:1个控制+1个奶控制位推荐:彩武沉默，没有彩武沉默用月光使者!</li><li>奶位推荐:优先彩武葫芦爷爷!小鹿和琴女后补!</li><li>输出位:输出位就比较多选择了，骨弓，李白，巫妖王，影魔，铁扇，深渊女王，火女，暗器大师这些群攻输出都可以。</li><li>前排:前排主要是能顶且有回复能力的，比如:小丸丸，船长，黄毛，复仇者，黑骑，白骑。具体可根据自己的英雄培养情况去调整。</li><li>后补位顺序:奶，前排，输出，奶/前排，前排!战斗过程战斗过程只需要按出战技能就可以了，带缓慢愈合的话，只要在英雄半血的时候按一下，其他时候不用管!</li></ol><p>钓鱼攻略图鉴：</p><p>几何王国的钓鱼系统是这个游戏很关键的子系统，我今天才开的图六，一天就出了4个藏品(额外还有个紫金圣杯)，开图六当天就把天使与恶魔钓齐全了，应该算全服最快的了吧，所以我今天浅谈一下钓鱼系统。 <img src="'+f+'" alt=""><img src="'+P+'" alt=""></p><p>在钓鱼玩藏品法中，需要掌握一些特殊方法能快速集齐图鉴，获得大量的百分比属性，提高自己游戏属性，后期战力越高加成越高!</p><p><img src="'+k+'" alt=""></p><p><strong>藏品最核心的就是拾荒属性，四个渔具建议，三个都洗练成拾荒属性，虽然废点钻石，但是后期大幅度加成游戏属性，这点钻石又算什么?(请不要喷我，因为我给游戏群玩家解答就是这样，他还一直喷我)。当然在饵料中，使用幸运星能大幅度增加拾荒属性，提高获得收藏品的几率，此外不同收藏品也存在不同地图产出，使用幸运星饵料则额外提高概率，我给大家发布一下收藏品的全套获得来源吧!</strong></p><p><img src="'+C+'" alt=""></p><p><img src="'+B+'" alt=""></p><h2 id="精灵攻略" tabindex="-1">精灵攻略 <a class="header-anchor" href="#精灵攻略" aria-label="Permalink to &quot;精灵攻略&quot;">​</a></h2><p>十大大众精灵搭配大全</p><h3 id="战甲虫" tabindex="-1">战甲虫 <a class="header-anchor" href="#战甲虫" aria-label="Permalink to &quot;战甲虫&quot;">​</a></h3><p>技能1:甲壳战斗开始给自身施加一个相当于最大生命值9%的护盾，效果持续20秒。</p><p>技能2:底力自身生命首次低于40%时启动底力技能，受到的远程伤害降低6%，效果持续20秒。</p><p>搭配分析:战甲虫的技能如果给前排佩戴，第一个属性魔法增伤就会废掉，因为前排英雄目前没有魔法伤害的。所以如果给后排巫妖或者狐狸带防止火枪队的话，实测与扎达姆的效果差不多推荐英雄:前排或法师</p><h3 id="铁人7号" tabindex="-1">铁人7号 <a class="header-anchor" href="#铁人7号" aria-label="Permalink to &quot;铁人7号&quot;">​</a></h3><p>(没有大地暴君时可暂时替代)</p><p>技能1:共鸣程序自身重伤效果增加3%，每阵亡一名友军额外增加6%重伤效果(最多叠加3层)。技能2灵魂压缩每阵亡一名敌人发动一次灵魂压缩，10秒内增加自身8%物理增伤与8%法增伤(重复触发可刷新时间，不可叠加)。</p><p>搭配分析:铁人7号适合单一输出型英雄，但是自身攻击中缺少带重伤的英雄!推荐英雄:狐狸，白牛，神罗，复仇(自身变身期间有减疗效果)</p><h3 id="星空鲸" tabindex="-1">星空鲸 <a class="header-anchor" href="#星空鲸" aria-label="Permalink to &quot;星空鲸&quot;">​</a></h3><p>技能1:鲸之忍耐自身受到控制或沉默效果时，立即回复自身4%最大生命(冷却9秒)。技能2:星空守护自身生命低于35%，且处于控制或沉默效果时，自身在2.5秒受到的伤害降低12%(冷却6秒)。</p><p>搭配分析:前排释放技能的次数会偏多，所以受到控制的次数会更多，触发回血的次数也会最大化!而且前期沉默比较强势，星空鲸非常不错。</p><p>推荐英雄:物理英雄或前排</p><h3 id="豆豆鱼" tabindex="-1">豆豆鱼 <a class="header-anchor" href="#豆豆鱼" aria-label="Permalink to &quot;豆豆鱼&quot;">​</a></h3><p>技能1:干扰自身释放控制类型技能时，对敌人的控制时间增加15%。</p><p>技能2:摧毁攻击陷入控制效果的敌人时，伤害增加7%。</p><p>搭配分析:根据豆豆鱼的技能和跟随属性来看，豆豆鱼可搭配控制类的辅助英雄和法师英雄，推荐英雄:月光使者，沉默，巫妖王，冰女，双头龙</p><h3 id="小火灵" tabindex="-1">小火灵 <a class="header-anchor" href="#小火灵" aria-label="Permalink to &quot;小火灵&quot;">​</a></h3><p>技能1:净化每隔16秒净化自身部分负面效果，同时增加自身5%免控率(最多叠加4层)。</p><p>技能2:灵能每次净化后，有20%概率使自身在5秒内进入减益免疫状态，并且增加自身4%攻击。</p><p>搭配分析:小火灵主要功能是解除负面效果和增加伤害，所以自身能解控的英雄自然就用不上了!</p><p>推荐英雄:输出型战士或后排输出。</p><h3 id="迷你菇" tabindex="-1">迷你菇 <a class="header-anchor" href="#迷你菇" aria-label="Permalink to &quot;迷你菇&quot;">​</a></h3><p>技能1:衰弱光环当前效果:进入战斗后开启衰弱光环，减少自身周围敌人3%攻击与5%移动速度技能2:衰弱反击自身受到远程攻击时，对攻击者施加衰弱效果，在5秒内减少攻击者6%攻击速度。</p><p>搭配分析:这个毫无疑问是前排带的。但是更适合推进能力比较强的前排才能发挥最大优势推荐英雄:小丸丸，熊猫，疾风忍者，猴子，白牛</p><h3 id="好人蝶" tabindex="-1">好人蝶 <a class="header-anchor" href="#好人蝶" aria-label="Permalink to &quot;好人蝶&quot;">​</a></h3><p>技能1:幻音自身生命首次低于30%时，发动一次幻音尖啸，降低所有敌军20%攻击速度，持续15秒。技能2:迷乱自身生命首次低于30%时，释放一次迷乱烟雾，降低所有敌军25%受伤回能效果，持续15秒</p><p>搭配分析:这个我也是推荐给前排带，牺牲前排给后排输出创造机会。但是只能是死的较快的一个前排!不要给主T带!推荐英雄:末曰，白骑，船长，剑圣，猴子，白牛</p><h3 id="小电精" tabindex="-1">小电精 <a class="header-anchor" href="#小电精" aria-label="Permalink to &quot;小电精&quot;">​</a></h3><p>技能1:反射冲击3秒内受到20%最大生命值的伤害时，发动反射冲击减少周围敌人12%移动速度与0.5%生命回复效果，持续4秒(冷却6秒)。</p><p>技能2:虚弱光波反射冲击会额外减少敌人4%物理抗性与4%魔法抗性。</p><p>搭配分析:这个也是需要搭配前排的，恢复型主T前排可以用，能够发挥最大威力。推荐英雄:死骑，白骑，小丸丸，熊猫，末日，咕咕鱼</p><h3 id="悠悠狐" tabindex="-1">悠悠狐 <a class="header-anchor" href="#悠悠狐" aria-label="Permalink to &quot;悠悠狐&quot;">​</a></h3><p>技能1:控制抵抗当前效果:受到控制或沉默效果时，永久增加3%控制抗性(最多叠加5层)。</p><p>技能2:魔力闪烁受到控制或沉默效果时，有20%几率发动一次魔力闪烁解除控制与沉默效果(冷却6秒)。</p><p>搭配分析:受到控制概率可以加抗性，还有概率解控，作用跟小火灵很类似。因为前排释放技能的次数会偏多，受到控制的次数也会更多，所以触发增加控制抗性与解除沉默效果的次数也会最大化!推荐英雄:攻击型前排或后排</p><h3 id="厚礼蟹" tabindex="-1">厚礼蟹 <a class="header-anchor" href="#厚礼蟹" aria-label="Permalink to &quot;厚礼蟹&quot;">​</a></h3><p>技能1:近战抵抗受到近身攻击时有30%几率在5秒内增加自身2%防御(最多叠加3层，每次触发后可刷新持续时间)技能2:攻守转换自身处于己方半场时增加5%击退抗性，处于敌方半场时增加3%击退效果。</p><p>搭配分析:这个还是适合推力比较强力的前排英雄!才能发挥最大威力!推荐英雄:小丸丸，熊猫，白牛</p><h3 id="毁灭之牙" tabindex="-1">毁灭之牙 <a class="header-anchor" href="#毁灭之牙" aria-label="Permalink to &quot;毁灭之牙&quot;">​</a></h3><p>精灵技能A:暴烈</p><p>进入战斗后开启暴烈之力，降低自身40%</p><p>暴击伤害，增加12%暴击率，持续到战斗结束!</p><p>精灵技能B:斗魂</p><p>自身每次暴击都会触发斗魂,增加自身1%攻击，持续5秒(最多加5层,每次触发后可刷新持续时间)</p><p>搭配方式:</p><p>推荐和法师搭配(优先:狐狸)</p><p>推荐理由: 增加暴击率与攻击力，进一步加强狐狸的暴力输出!</p><h3 id="魔能女士" tabindex="-1">魔能女士 <a class="header-anchor" href="#魔能女士" aria-label="Permalink to &quot;魔能女士&quot;">​</a></h3><p>精灵技能A:魔能潮汐</p><p>进入战斗后12秒后，自身启动魔能潮汐每秒获得5点能量，如果自身阵亡，立即为全体友军回复120点能量! 精灵技能B:法力共鸣给攻击最高的友方单位和自身增加4%的防自身每次释放大招后发动一次法力共鸣,御，持续10秒!</p><p>搭配方式: 推荐和射手搭配(优先:骨弓)</p><p>推荐理由: 增加防御力与回能，使得骨弓兼顾肉盾与输出双能!</p><h3 id="秘法女巫" tabindex="-1">秘法女巫 <a class="header-anchor" href="#秘法女巫" aria-label="Permalink to &quot;秘法女巫&quot;">​</a></h3><p>精灵技能A:能量推毁</p><p>自身受到攻击时有25%概率释放一次能量摧毁，减少攻击者35点能量(冷却3秒) 精灵技能B:能量回溯自身受到攻击时有25%概率触发一次能量回溯，增加自身35点能量(令却3秒)</p><p>搭配方式: 推荐和前排搭配(优先:船长) 推荐理由: 限制对方回能，加强船长自身回能快速放大!加速快速收割战场!</p><h3 id="赤色彗星" tabindex="-1">赤色彗星 <a class="header-anchor" href="#赤色彗星" aria-label="Permalink to &quot;赤色彗星&quot;">​</a></h3><p>精灵技能A:蕾势待发 每3秒增加自身0.4%攻击和0.4%防御(最多叠加10层)! 精灵技能B:力量窃取进入战斗后随机偷取一名敌人5%攻击附加给自身，效果持续15秒(偷取的攻击最多不超过自身的7%)! 搭配方式: 推荐和法师搭配(优先:巫妖) 推荐理由: 增加自身伤害，进一步增加巫妖群伤的威力，同时还能增加自身防御力，增加生存力!</p><h3 id="翡翠之主精灵" tabindex="-1">翡翠之主精灵 <a class="header-anchor" href="#翡翠之主精灵" aria-label="Permalink to &quot;翡翠之主精灵&quot;">​</a></h3><p>技能A:受损充能时，每秒能量回复效果增加20%，自身单次受到超过20%最大生命的伤害持续6秒(重复触发可刷新时间，不可鲁加)!</p><p>精灵技能B:生命流转 自身每损失10%最大生命，增加7%受伤回能效果!</p><p>搭配方式: 推荐和前排搭配(优先:黑骑)</p><p>推荐理由: 帮助受伤回能加速，帮助黑骑快速放大!进一步增加生存力!</p><h3 id="大地暴君精灵" tabindex="-1">大地暴君精灵 <a class="header-anchor" href="#大地暴君精灵" aria-label="Permalink to &quot;大地暴君精灵&quot;">​</a></h3><p>技能A:碎甲进入战斗的第12秒后,每5秒增加自身3%破甲(最多叠加6层)! 精灵技能:硬化自身释放大招时额外获得一个相当于自身4%最大生命的护盾，效果持续5秒</p><p>搭配方式: 推荐和前排搭配(优先:神罗</p><p>推荐理由: 破甲加生命盾，使得神罗兼顾输出与生存力!</p><p>规则：</p><p>A:精灵技能可以升级，且最高可以从1级升到10级，所以目前的技能展示的百分比还可以不断提升!不断加强!(材料:天使之羽)</p><p>B:月之精华每次抽需要200=1积分，并且积分只能在精灵周活动方可兑换材料!</p><p>C:进阶到永恒品质，会得到一条属性加持!(材料:神话精灵进阶石)</p><p>D:普通品质20级-&gt;稀有品质</p><p>稀有品质30级-&gt;传说品质</p><p>传说品质40级-&gt;神话品质</p><p>神话品质50级-&gt;永恒品质</p><p>E:召唤等级最高15级，越高级就能抽到越好的精灵资源!</p><p><img src="'+D+'" alt=""></p><p>接下来也是很关键的就是四个渔具我们应该怎么点升级呢? 很多大佬盲目点，不仅没有把藏品钓起来，还浪费不少钻石和时间，下面就是我渔具属性，对没错哦，就是重点升级鱼漂和鱼钩，这两个是核心，鱼竿和鱼线我认为黄色就够了</p><p><img src="'+N+'" alt=""></p><p>接下来请大家看一下我的藏品宝库吧</p><p><img src="'+A+'" alt=""></p><p>有同学说想看看鱼缸我自己的是怎么收藏的，那我就顺便把鱼缸藏品鱼也发出来。 <img src="'+S+'" alt=""><img src="'+U+'" alt=""><img src="'+v+'" alt=""></p><p>最后一个问题，很多同学开了图五想钓大王具足虫，我个人觉得拾荒属性高，换成海澡一直无脑钓，没必要再去洗练海底生物属性(不清楚后期策划会不会调整)</p>',266)])])}const K=a(w,[["render",E]]);export{I as __pageData,K as default};
